/**
 * Словарь области: «к какому файлу относится этот вопрос».
 *
 * Вынесен из `graph.mjs` не ради красоты. Инструмент задаёт вопросы разного
 * рода — про тесты, про поведение в браузере, про публичную поверхность полки, —
 * и каждый из них применим не ко всякому файлу. Пока это решение выводилось на
 * месте, оно выводилось по-разному: где-то учитывали расширение, где-то тест,
 * где-то ни того ни другого. Три дефекта подряд были именно забытым слагаемым
 * такой комбинации — вопрос срабатывал на README и на тестовом файле, у которых
 * спрашиваемого свойства нет вовсе.
 *
 * Поэтому здесь **чистые функции от пути**, без чтения диска и без состояния:
 * их можно прогнать таблицей, что и делают оба слоя — набор тестов и
 * самопроверка самого инструмента.
 */

// Модуль импортирует сам себя — намеренно, ради единственного списка имён.
// Пространство имён ESM заполнено к моменту ВЫЗОВА (а не разбора), поэтому
// `selfCheck` видит через него все экспорты, включая заведённые завтра. Второй
// список — рукописная таблица соответствия — здесь стоял и был третьей копией
// тех же имён; копия источника истины расходится первой.
import * as vocabulary from "./graph.predicates.mjs";

const NEWLINE = String.fromCharCode(10);
const SEP1 = String.fromCharCode(59);
const SEP2 = String.fromCharCode(58);

/** Тест: лежит в папке слоя `tests/` либо назван суффиксом. */
// Имена тестов бывают двух видов, и второй не реже первого. `.spec` — форма из
// мира, откуда пришли раннеры: её везут все поколения инструментов, и живой
// проект зовёт свои тесты так же часто, как `.test`.
//
// Пока опознавался один вид, инструмент отвечал «тестовых файлов: ноль» на
// проекте, где раннер собирал тридцать шесть зелёных тестов, — а сверка
// покрытия тестов была при этом ЗЕЛЕНОЙ, потому что не видела ничего. Найдено
// посадкой в чужую библиотеку.
export const isTestPath = (f) =>
  /\/tests\//.test(f) ||
  /\/__tests__\//.test(f) ||
  /\.(test|spec)\.[jt]sx?$/.test(f);

/** Лист стилей. В граф импортов не входит — его подключает сборщик.
 *
 * Собираются ВСЕ языки стилей, а не один. Пока опознавался только `.scss`,
 * проект на обычных модулях CSS проходил как проект без стилей вовсе: сто
 * девяносто непустых строк — больше, чем весь его код — не попадали ни в карту,
 * ни в замер чтения, ни в поиск предмета для раздела планки о стилях. Раздел
 * из-за этого выключался молча, и сверка применимости была зелёной. */
export const isStylePath = (f) => /\.(css|scss|sass|less|styl)$/.test(f);

/** Документ. */
export const isDocPath = (f) => /\.md$/.test(f);

/**
 * Исполняемый модуль: то, у чего есть форма и ответ, то есть контракт. Тест
 * сюда не входит — он сам проверка, поверхности у него нет.
 */
export const isCodePath = (f) => /\.[jt]sx?$/.test(f) && !isTestPath(f);

/**
 * То, чья правка меняет наблюдаемое поведение продукта: код или стиль. Стиль
 * входит намеренно — в графе импортов его не видно, а краску он меняет.
 * Документ и тест — нет: первый ничего не исполняет, второй и есть проверка.
 */
export const touchesRuntime = (f) => isCodePath(f) || isStylePath(f);

/**
 * Позиция в строке приходится на комментарий. Нужен там, где сверка спрашивает
 * «существует ли имя в ИСПОЛНЯЕМОМ тексте»: иначе она держится за собственное
 * эхо — переименовали по всему коду, оставили старое имя в комментарии, и
 * запись считается живой.
 */
export const inComment = (line, at) => {
  const before = line.slice(0, at);
  return before.includes("//") || /^\s*(\*|\/\*)/.test(line);
};

/**
 * Текст модуля БЕЗ блочных комментариев: граф строится по коду, а не по
 * рассказу о нём.
 *
 * Разбор импортов шёл по сырому тексту, и закомментированный пример в хвосте
 * файла давал НАСТОЯЩЕЕ ребро графа: файл импортировал сам себя и стоял в
 * собственном радиусе поражения. Хуже другое — закомментированный импорт
 * числился живым потребителем, и мёртвый экспорт выглядел используемым.
 *
 * Снимается только комментарий, ОТКРЫТЫЙ С НАЧАЛА СТРОКИ, и это не
 * упрощение. Сочетание косой со звёздочкой сплошь и рядом стоит внутри строк
 * — любой образец пути вида двух звёздочек со слэшем несёт его, — и жадное
 * снятие съело бы код до следующего закрытия. Закомментированный же блок
 * начинается с начала строки всегда.
 *
 * Строчный комментарий тут ни при чём: образец импорта требует начала
 * строки, а две косые его не пускают.
 *
 * Переводы строк сохраняются: номера строк не должны поехать.
 */
export const codeOf = (text) =>
  text.replace(/^[ \t]*\/\*[\s\S]*?\*\//gm, (m) => m.replace(/[^\n]/g, ""));
/**
 * Таблица случаев — **единственный** источник для обоих слоёв: набора тестов и
 * самопроверки инструмента. Две отдельные таблицы разошлись бы, и разошлись бы
 * молча, потому что обе зелёные.
 *
 * Случаи взяты не из головы: каждая строка с пометкой «дефект» — тот вход, на
 * котором инструмент уже отвечал неверно.
 */
/** Дыра в строке протокола свода по планке — чистая её часть.
 *
 * На входе строка вида `род|исход|адрес|что|судьба` — ровно те ячейки, из
 * которых состоит запись протокола. На выходе название дыры либо пустая
 * строка: дыр нет.
 *
 * Здесь только то, что решается из самой записи: закрытый словарь исходов,
 * закрытый словарь судеб, законность судьбы при роде задачи, вид адреса.
 * Существует ли файл, есть ли в нём такая строка и числится ли адрес в
 * правленом — вопросы к диску, и они остаются инструменту.
 *
 * Вынесено сюда затем, что внутри режима это держалось одноразовой пробой
 * при заведении. Здесь его гоняет самопроверка при каждом вызове.
 */
/** Беспредметен ли критерий планки НА ЭТОЙ ПРАВКЕ — чистая её часть.
 *
 * На входе строка `<критерий>|<признак>=<0|1>,…` — сам критерий и то, что
 * инструмент замерил в предмете правки. На выходе причина словами либо
 * пустая строка: предмет есть, и отвечает сессия.
 *
 * **Зачем.** Раздел политики объявляется живым или мёртвым на ВЕСЬ проект, и
 * мёртвый в протокол не попадает вовсе. Живой попадает целиком — даже когда
 * эта правка его предмета не касается: раздел стилей живой, потому что листы
 * у проекта есть, а правка тронула один файл кода. Сессия писала «предмета
 * нет» руками по одиннадцати строкам, и это почти сорок процентов всей
 * работы свода — замерено на проходе по стенду: из ста сорока девяти строк
 * пятьдесят девять были «нет предмета».
 *
 * **Отбор узкий намеренно.** Сюда попадает только то, что доказуемо из
 * предмета: файла такого рода в правке нет, эффекта нет, списка нет,
 * манифест не тронут. Суждения — «предметной логики тут нет», «горячего
 * пути нет» — не попадают и попасть не могут: машина их не выводит, а
 * поставленное ею «нет предмета» там, где предмет есть, — это ровно то
 * зелёное без проверки, от которого свод и заведён.
 *
 * **Поставленное не заперто.** Инструмент заполняет клетку, сессия вправе
 * переписать: строка из протокола не исчезает, исчезает только её набивка.
 */
export const barNoSubject = (row) => {
  const [id, flagText] = row.split("|");
  const flag = new Map(
    (flagText ?? "")
      .split(",")
      .filter(Boolean)
      .map((one) => one.split("="))
      .map(([k, v]) => [k, v === "1"]),
  );
  const no = (k) => flag.get(k) === false;

  // Правка без единого файла кода: разделы, чей предмет — код и только код.
  const CODE_ONLY = new Set([
    "B1",
    "B2",
    "B2-бис",
    "B3",
    "B4",
    "B5",
    "B6",
    "B6-бис",
    "B7",
    "B8",
    "B9",
    "B10",
    "B11",
    "B12",
    "B13",
    "C1",
    "C2",
    "C3",
    "C4",
    "C5",
    "C6",
    "C6-бис",
    "C7",
    "C8",
    "C8-бис",
    "C8-тер",
    "C9",
    "C10",
    "C11",
    "C12",
    "C13",
    "C14",
    "C15",
    "C16",
    "D1",
    "D2",
    "D3",
    "D4",
    "D5",
    "E1",
    "E2",
    "E3",
    "E4",
    "E5",
    "E6",
    "E7",
    "E8",
    "E9",
    "E10",
    "E11",
    "E12",
    "E13",
    "F1",
    "F2",
    "F3",
    "F4",
    "M1",
    "M2",
    "M3",
    "M4",
    "M5",
    "M6",
  ]);
  if (CODE_ONLY.has(id) && no("code"))
    return "файла кода в предмете правки нет";

  // Правка без единого листа стилей. `C7-бис` и `O5` сюда НЕ идут: у них
  // второй конец в коде, и правка кода их предмета касается. `O3` и `O4-тер`
  // — тоже: число раскладки и размер окна берут и кодом, и без листа.
  const STYLE_ONLY = new Set([
    "O1",
    "O2",
    "O2-бис",
    "O4",
    "O4-бис",
    "O4-кватер",
    "O5-бис",
  ]);
  if (STYLE_ONLY.has(id) && no("style"))
    return "листа стилей в предмете правки нет";
  if ((id === "O3" || id === "O4-тер") && no("style") && no("code"))
    return "ни листа стилей, ни кода в предмете правки нет";

  // «Нет предмета» ставится только по признаку-НАДМНОЖЕСТВУ: признак
  // обязан покрывать всё, о чём критерий, иначе машина объявляет чистым то,
  // чего не видела. Замерено на разборе узла: отмена и устаревание (`C9`)
  // закрывались признаком «асинхронное», а устаревший результат там жил в
  // подписке и таймере — и дефект этого самого критерия прошёл свод
  // строкой «нет предмета». Движение задаётся и листом, и кодом кадров.
  // Жизненный цикл движения — тоже: переход листом стилей — движение без
  // единого таймера в коде.
  if ((id === "N6" || id === "N1") && no("style") && no("time"))
    return "ни листа стилей, ни кадров и таймеров в предмете правки нет";

  // Критерии о СУЩЕСТВУЮЩИХ тестах. `J2`, `J3`, `J9-бис`, `J9-тер` тут
  // неуместны: они спрашивают, написан ли тест, а не каков он.
  const ABOUT_TESTS = new Set([
    "J1",
    "J4",
    "J5",
    "J6",
    "J7",
    "J8",
    "J9",
    "J10",
    "J13",
  ]);
  if (ABOUT_TESTS.has(id) && no("test"))
    return "тестов у предмета правки нет ни одного";

  // Отложенное во времени: эффект, таймер, наблюдатель, кадровый цикл.
  // `C5` сюда не входит: порядок бывает и без времени — синхронная рассылка
  // подписчикам, порядок подключения, порядок инициализации модулей.
  const ABOUT_TIME = new Set(["C12", "F4", "M3", "N3"]);
  if (ABOUT_TIME.has(id) && no("time"))
    return "ни эффекта, ни таймера, ни наблюдателя в предмете правки нет";

  // Ресурс и устаревание живут и во времени, и в асинхронном: подписка,
  // таймер, запрос с отменой. Беспредметны, только когда нет ни того, ни
  // другого.
  const TIME_OR_ASYNC = new Set(["C9", "F1", "F2"]);
  if (TIME_OR_ASYNC.has(id) && no("time") && no("async"))
    return "ни эффекта, ни таймера, ни асинхронных операций в предмете правки нет";

  // Списки: отрисовка перечислением.
  const ABOUT_LIST = new Set(["M4", "G6-бис"]);
  if (ABOUT_LIST.has(id) && no("list")) return "списков в предмете правки нет";

  // Зависимости: их спрашивают, когда тронут манифест.
  const ABOUT_DEPS = new Set(["R1", "R1-бис", "R2"]);
  if (ABOUT_DEPS.has(id) && no("manifest"))
    return "манифест этой правкой не тронут";

  // Парные копии: их у проекта может не быть вовсе.
  if (id === "A5-бис" && no("forks")) return "парных копий проект не объявлял";
  // Затронутая гарантия — та, что называет узел области. Ни одна не
  // называет — тест гарантии правке не о чем прогонять. О новой
  // возможности (`J12`) так не судят: её гарантии ещё нет по построению.
  if (id === "J11" && no("promise"))
    return "ни одна гарантия поведения не называет узел этой области";

  return "";
};
/** Архитектурное ядро планки: критерии о ФОРМЕ вещи, а не о её деталях.
 *
 * Про них спрашивают основание даже на исходе «чисто». Остальные критерии
 * закрываются пустой клеткой, и это законно: их нарушение видно в строке, а
 * их отсутствие — тоже.
 *
 * **Почему список закрытый и почему именно эти.** Нарушение здешнего
 * критерия не видно в строке. Его видно только в целом: узел, отвечающий на
 * три вопроса, в каждой своей строке безупречен. Поэтому вердикт по ним
 * обязан назвать, ЧТО именно проверено, — иначе он неотличим от
 * непроверенного.
 *
 * **Замерено на себе.** Проход по ста пятидесяти трём критериям закрыл
 * `A1`, `A6`, `C7-бис`, `O1` и `B1` словом «чисто» на узле, который
 * нарушает все пять: описание узла в карте требует союза «и» трижды, текст
 * лежит в разметке лишним разом ради замера, отступ живёт двумя
 * представлениями, а компонент зашивает оформление при записанном решении
 * отдавать вид вызывающему целиком. Ни одна из пяти строк не солгала —
 * каждая просто ничего не сказала.
 */
const BAR_CORE = new Set([
  "A1",
  "A1-бис",
  "A1-тер",
  "A2",
  "A5",
  "A6",
  "A6-бис",
  "A7-бис",
  "A9",
  "A9-бис",
  "A10",
  "A11",
  "A12",
  "A13",
  "A14",
  "A15",
  "A16",
  "B2",
  "B7",
  "C1",
  "C4",
  "C6",
  "C6-бис",
  "C7",
  "C7-бис",
  "C14",
  "C16",
  "I1",
  "I2",
  "I4",
  "O1",
]);

// Состав дополнен, когда проход стал уровневым: второй писатель и владелец
// источника, отдача изменяемого наружу, узел с двумя ответственностями,
// оркестрация вперемешку с механизмом, цикл и место узла в раскладке — тоже
// форма целого, невидимая в строке.

/** Уровень строки модели — по её виду. Один источник на инструмент и словарь:
 * разойдясь, модель клала бы строку на один уровень, а правило согласия
 * искало бы её на другом. */
export const MODEL_LEVEL = {
  // Признаки, видимые текстом: нарушение видно в строке, и о строке
  // спрашивает критерий единицы.
  число: "единица",
  флаг: "единица",
  перехват: "единица",
  кортеж: "единица",
  // Признаки узла: правка взятого импортом и изменяемое модуля — о том, кто
  // владеет; россыпь булевых полей — о форме состояния; порознь — один ли
  // это узел.
  мутация: "узел",
  модульное: "узел",
  флаги: "узел",
  порознь: "узел",
  место: "слой",
  ответственность: "узел",
  поверхность: "узел",
  зависит: "узел",
  пользуется: "узел",
  состояние: "узел",
  ресурс: "узел",
  слой: "слой",
  граница: "слой",
  направление: "слой",
  цикл: "слой",
  устойчивость: "слой",
  источник: "приложение",
  сосед: "приложение",
  писатель: "приложение",
  связь: "приложение",
  наружу: "приложение",
  размах: "приложение",
  каталог: "приложение",
  радиус: "приложение",
  гарантия: "приложение",
  хранение: "приложение",
  // Признаки по всей планке. Единица — то, что видно в строке; узел — то,
  // что видно по файлу целиком; приложение — то, что видно только по проекту.
  внешнее: "единица",
  запись: "единица",
  время: "единица",
  обход: "единица",
  страж: "единица",
  бросок: "единица",
  раскладка: "единица",
  поиск: "единица",
  комментарий: "единица",
  имя: "единица",
  величина: "единица",
  мемо: "единица",
  однократно: "единица",
  эффект: "единица",
  команда: "единица",
  постоянный: "единица",
  тест: "единица",
  стиль: "единица",
  доступность: "единица",
  вставка: "единица",
  журнал: "единица",
  измерение: "единица",
  текст: "единица",
  разметка: "узел",
  пакет: "узел",
  гонка: "узел",
  список: "узел",
  частое: "узел",
  контекст: "узел",
  ограничение: "узел",
  требование: "узел",
  переходы: "узел",
  проброс: "узел",
  размер: "узел",
  создаёт: "узел",
  тесты: "узел",
  мутации: "узел",
  движение: "узел",
  мёртвое: "узел",
  обобщение: "единица",
  дубль: "единица",
  всегда: "единица",
  необязательные: "единица",
  целое: "узел",
  вид: "узел",
  сквозь: "узел",
  кэш: "узел",
  рост: "узел",
  права: "единица",
  секрет: "единица",
  порядок: "узел",
  идентификаторы: "узел",
  близнец: "приложение",
  повтор: "приложение",
  зависимость: "приложение",
  приглушение: "приложение",
};

/** Уровни прохода по порядку: от строки к целому. */
export const LEVEL_ORDER = ["единица", "узел", "слой", "приложение"];

/** Номера строк модели, названные текстом: по одному и диапазоном
 * «П3–П7». Номер называется целиком: П2 не отвечает за П20.
 *
 * Диапазон — опора, а не ответ. Строку, о которой модель СПРАШИВАЕТ, —
 * сдвиг, вопрос к основанию, — называют её номером: `alone` отдаёт только
 * такие. Прежде «П1–П17 разобраны» отвечало на каждый вопрос модели разом,
 * не ответив ни на один: замерено кривой кнопкой на мини-стенде, где так
 * прошли новое состояние, обход входа чужой папки и второй источник. */
const citedIds = (text, alone = false) => {
  const out = new Set();
  for (const m of (text ?? "").matchAll(
    /(^|[^А-Яа-яA-Za-z0-9])П([0-9]+)(?:\s*[–—-]\s*П?([0-9]+))?(?![0-9])/g,
  )) {
    if (alone && m[3] !== undefined) continue;
    const from = Number(m[2]);
    const to = m[3] === undefined ? from : Number(m[3]);
    for (let k = from; k <= Math.max(from, to); k += 1) out.add(k);
  }
  return out;
};

/** На чём стоит «чисто»: вход — `основание|П1=база,П2=код,…`, выход —
 * `база`, если каждая названная им строка модели взята из записи базы,
 * `сессия`, если каждая дописана сессией, иначе пусто. Строка базы верна,
 * пока верна запись, — и печать называет, сколько «чисто» стоит только на
 * таких. */
export const barRestsOn = (row) => {
  const cut = row.lastIndexOf("|");
  const origin = new Map(
    row
      .slice(cut + 1)
      .split(",")
      .filter(Boolean)
      .map((one) => {
        const [mid, from] = one.split("=");
        return [Number(mid.slice(1)), from];
      }),
  );
  const cited = [...citedIds(row.slice(0, cut))].filter((n) => origin.has(n));
  if (cited.length === 0) return "";
  const kinds = new Set(cited.map((n) => origin.get(n)));
  return kinds.size === 1 && (kinds.has("база") || kinds.has("сессия"))
    ? [...kinds][0]
    : "";
};

/** Чем записан известный дефект, если факт модели им является: пункт долга
 * перехода либо открытая строка реестра находок. Пишется в пометке строки
 * модели после точки: «против правила · долг перехода». */
export const BAR_OWED = ["долг перехода", "находка реестра"];
/** Факт, названный записью решения: разработчик сказал «оставляем» либо «не
 * сейчас», и факт законен. Пишется в пометке так же, после точки. */
export const BAR_HELD = "решение";
const owedSplit = (raw) => {
  for (const word of [...BAR_OWED, BAR_HELD]) {
    if (raw === word) return ["", word];
    if (raw.endsWith(" · " + word)) return [raw.slice(0, -(word.length + 3)), word];
  }
  return [raw, ""];
};
/** Пометка строки модели — чем записан известный дефект, либо пусто. */
export const barOwedOf = (mark) => {
  const word = owedSplit(mark ?? "")[1];
  return BAR_OWED.includes(word) ? word : "";
};

/** Какие критерии отвечают за факт модели. Известный дефект, записанный
 * фактом, спрашивается с них: ребро против правила и внутренность мимо
 * входа — с направления и поверхности, цикл — с ацикличности, второй
 * писатель — с одного писателя. */
export const BAR_FACT_CRITERIA = {
  направление: ["A5"],
  граница: ["A5", "B7"],
  цикл: ["A9-бис"],
  писатель: ["C6-бис"],
};

/** Модель одной строкой — `П1:вид:пометка:сдвиг;…` — разобранная. */
const modelRowsOf = (text) =>
  (text ?? "")
    .split(";")
    .filter(Boolean)
    .map((one) => {
      const [mid, sort, raw, delta] = one.split(":");
      const [mark, word] = owedSplit(raw ?? "");
      return {
        mid,
        n: Number((mid ?? "").slice(1)),
        sort,
        mark,
        owed: BAR_OWED.includes(word) ? word : "",
        held: word === BAR_HELD,
        delta: delta ?? "",
        level: MODEL_LEVEL[sort] ?? "",
      };
    });

/** Ядро, чьё «чисто» обязано опереться на МОДЕЛЬ предмета: назвать строку
 * модели — зависимость, состояние, ресурс, связь, выход наружу, — на которой
 * вердикт стоит. Модель собирает инструмент из кода и базы, и опора на неё
 * отличает проверенное от проставленного: основание словами можно написать,
 * не глядя в код, а номер строки модели — только прочитав её.
 *
 * Два пункта ядра не спрашиваются: лист стилей и граница языков в модель не
 * входят, опереться там не на что. */
const BAR_MODEL_FREE = new Set(["O1", "C7-бис"]);
export const barCitesModel = (id) =>
  BAR_CORE.has(id) && !BAR_MODEL_FREE.has(id);

/** Разложение критерия по предметам уровня.
 *
 * Вход — `критерий|уровень`. Выход — `узел`, `слой` либо пустая строка.
 * Ядро уровня узла спрашивают по каждой тронутой единице переноса, уровня
 * слоя — по каждому слою; остальное — одной строкой на работу. Одна строка
 * на правку двух узлов закрывала вопрос одного ответом о другом: «одна
 * ответственность» про чистый узел проходила при втором, который её нарушал.
 * Ядро приложения не раскладывают: приложение одно. */
export const barSplitOf = (row) => {
  const [id, level] = row.split("|");
  if (!BAR_CORE.has(id)) return "";
  return level === "узел" || level === "слой" ? level : "";
};

// --- чем держится критерий: данные модели свода ---------------------------
//
// Вопросы модели к критериям планки — данные, а не ветки разбора: какая
// строка модели о каком критерии спрашивает, какая режет сама, какая
// опровергает «нет предмета». Данными они затем, чтобы по ним же печаталась
// матрица «критерий → чем держится» и чтобы новый критерий без решения о
// своём держателе ронял тест обвязки. Прежде вопросы стояли ветками внутри
// разбора, и ответить, сколько критериев держится одним вниманием, было
// нечем: замерено по всей планке — таких было `146` из `197`.
//
// Запись: `ids` — критерии; `sort` — вид строки модели; `mark` — пометка,
// строкой либо списком; `scope` — `fresh` (только сдвиг), `brought` (на
// правке — сдвиг, на чтении — всё) либо всё; `words` — что сказать, когда
// «чисто» строку не назвало. `{состояние}` в словах — чья это строка: правка
// завела состояние либо оно в предмете есть.

