/** Сверки, чьи находки модель свода несёт строками сама — ребро против
 * правила, цикл, граница, второй писатель — и судит правилами согласия на
 * той строке, где факт лежит. Красная, такая сверка с исходом не спорит:
 * спор дублировал бы модель и ставил бы находку не на ту строку — цикл двух
 * слоёв требовал бы ответа в обоих, ребро — и у слоя, в который оно идёт. */
export const BAR_CHECKS_MODELLED = new Set([
  "Правила направления",
  "Архитектурный факт назван записью",
]);

/** Сверка, держащая несколько критериев находками разного вида: строка
 * находки спорит с тем критерием, о чьём виде она. */
export const BAR_CHECK_KINDS = {
  "Запись о состоянии не спорит с кодом": {
    "C6-бис": /ни владельцем, ни писателем/,
    K6: /«Время жизни»/,
  },
};

/** Правила линта, которые держат критерий: цепочка проверок краснеет на
 * нарушении в любом файле, который линт разбирает. Здесь только правила,
 * которые семя конфига линта включает ошибкой, и только те, чьё срабатывание
 * видели на посаженном нарушении: предупреждение цепочку не роняет, а
 * правило, промолчавшее на посадке, держит одно название. Включены ли они
 * ошибкой, сверяет тест обвязки по семени. Имя — дословно, как его печатает
 * линт. */
