// --- формы нарушения, которых держатель не видит --------------------------
//
// Держатель видит одну форму нарушения, а другую форму того же нарушения —
// нет. Второй источник истины в адресе страницы модель не показывала, пока
// образец состояния знал одни хуки, и «чисто» по источнику истины стояло на
// модели, в которой этой формы не было: четыре посадки прошли мимо. Поэтому у
// каждого критерия, который держит машина, решено, каких форм его держатель
// не видит и почему, — либо набор записан закрытым с причиной. Формы
// печатаются на странице критерия, которую сессия читает, судя, и в матрице
// `bar-hold`: «чисто» по такой форме стоит на чтении, а не на модели.
// Критерий с машинным держателем без решения роняет режим и тест обвязки.
//
// Запись: список строк «форма — почему держатель её не видит» либо строка
// «закрыто: почему держатель видит каждую форму». Формы, общие нескольким
// критериям, названы один раз ниже.

/** Слепые пятна, общие нескольким критериям: одно описание на пятно. */
const UNSEEN = {
  dynamic:
    "ребро через динамический `import()` и `require` — граф строится по статическим строкам `import` и `export … from`",
  outside:
    "внешнее, которого нет в образце: клиенты сети кроме `fetch` и `axios`, `navigator`, `matchMedia`, буфер обмена, чтение файла, ответ стороннего пакета — образец перечисляет вызовы, а не род",
  wrapper:
    "внешнее через обёртку проекта, взятую импортом (`api.get`, `storage.read`), — обращение видно в обёртке, а в логике, которая её зовёт, его нет",
  network:
    "сеть через клиент, которого нет в образце, — образец знает `fetch`, `axios`, `XMLHttpRequest`, `WebSocket`, `EventSource` и `sendBeacon`",
  resource:
    "ресурс, которого нет в образце: медиапоток, адрес объекта `URL.createObjectURL`, `BroadcastChannel`, соединение базы — образец перечисляет пары «захват — снятие»",
  release:
    "снятие не на каждой ветке выхода и снятие не того экземпляра — срез ищет вызов снятия где угодно в файле, а не его ветку и довод",
  // Те же пятна у критериев, которые держит и линт: его правила судят уборку
  // эффекта, и сказать «срез не видит» без линта значило бы соврать.
  resourceLinted:
    "ресурс, которого нет ни в образце, ни в правилах линта: медиапоток, адрес объекта `URL.createObjectURL`, `BroadcastChannel`, соединение базы — образец перечисляет пары «захват — снятие», а правила линта судят слушатель, таймер, интервал и наблюдатели размера и пересечения",
  releaseLinted:
    "снятие не на каждой ветке выхода вне эффекта — срез ищет вызов снятия где угодно в файле, а правила линта судят уборку эффекта",
  race:
    "асинхронный результат, который пишут не сеттером: в хранилище, в ссылку, в поле — признак гонки ставится, когда в файле есть `await` либо `.then` и запись сеттером",
  flag: "флаг без пометки типа и без умолчания — признак ищет `: boolean` и умолчание `true` либо `false`",
  list: "список, который рисуют не через `.map` в разметке: компонент списка, цикл, виртуальный список — признак видит `.map` в фигурных скобках разметки",
  motion:
    "движение средствами, которых нет в образце: `setInterval` со сдвигом, `anime`, `react-transition-group`, `useTransition` — образец знает `requestAnimationFrame`, `animate`, `motion`, `gsap`, `useSpring` и движение листа стилей",
  method: "метод класса и объекта — тела признак ищет у `function` и у `const` со стрелкой",
  repeat:
    "повтор с переименованными именами, переставленными строками либо короче окна — повтор ищут совпадением нормализованных строк окном",
  log: "журнал через свою обёртку либо пакет журнала — признак видит `console`",
  measure:
    "измерение через пакет метрик, профилировщик либо `Date.now` — признак видит `performance.mark`, `measure`, `console.time` и `PerformanceObserver`",
  manifest:
    "зависимость, заведённая до работы, и любая зависимость на задаче чтения — строка спрашивает зависимости, которые правка добавила либо переставила",
  witness: (what, asks) =>
    what + " — признака текста нет; спрашивает свидетель «" + asks + "», ответ даёт чтение",
};

