/**
 * Прогон таблицы. Возвращает список расхождений — пустой, когда всё сходится.
 *
 * Инструмент зовёт это на КАЖДОМ запуске и отказывается работать при непустом
 * списке. Причина в том, что «запустить тесты после правки» иначе держится
 * памятью: набор гоняется, когда о нём вспомнили, а инструмент вызывают
 * постоянно — и сломанный словарь виден в тот же миг, а не в конце дня.
 *
 * Предикат берётся из собственного пространства имён модуля, а не из таблицы
 * соответствия рядом. Таблица тут стояла и была **третьим** рукописным списком
 * тех же имён — после списка в наборе тестов и списка покрытия; оба уже убраны
 * тем же движением. Стоила она не аккуратности: предикат со случаями, но не
 * внесённый в неё, ронял инструмент стек-трейсом `BY_NAME[name] is not a
 * function` — то есть словарь, чей контракт «отказаться внятно, а не ответить
 * неверно», отказывался невнятно. Проверено подсадкой.
 *
 * Имя из таблицы, которого в словаре нет вовсе (опечатка в случае), теперь
 * тоже расхождение, а не падение.
 */
export const selfCheck = () => {
  const failed = [];
  // Предикат БЕЗ ЕДИНОГО случая — не расхождение, а дыра: перебор ниже его
  // просто не встретит, и словарь промолчит о том, что половину его никто
  // не проверяет. Спрашивается это здесь, а не только набором тестов:
  // набор идёт своей командой, вне прогона проекта, и в проекте его зовут
  // только при правке обвязки. Инструмент же зовут постоянно, и здесь
  // гарантия словаря держится сама.
  const covered = new Set(PREDICATE_CASES.map(([name]) => name));
  for (const [name, value] of Object.entries(vocabulary))
    if (typeof value === "function" && value.length === 1 && !covered.has(name))
      failed.push(name + " — предикат области без единого случая");
  for (const [name, input, want] of PREDICATE_CASES) {
    const predicate = vocabulary[name];
    if (typeof predicate !== "function") {
      failed.push(`${name} — такого предиката в словаре нет`);
      continue;
    }
    const got = predicate(input);
    if (got !== want) failed.push(`${name}(${input}) = ${got}, ждали ${want}`);
  }
  return failed;
};

/** Язык модуля: TypeScript И обычный JavaScript.
 *
 * Умолчание обвязки — TypeScript, и половина планки стоит на его строгости. Но
 * умолчание говорит, на чём НАЧИНАЮТ проект, а не что инструмент способен
 * прочесть: живой проект на обычном JavaScript существует, и обвязку в него
 * сажают так же. Пока опознавался один язык, такой проект был для инструмента
 * ПУСТ — «файлов кода: ноль» при шести файлах на диске, — и молчали разом карта,
 * реестр тестов, замер чтения и поиск предмета для разделов планки.
 *
 * Расхождение с умолчанием этим не отменяется: оно называется отчётом посадки и
 * платится тем, что критерии о строгости проверять нечем. Но невидимость и
 * несогласие — разные вещи, и вторая лучше первой.
 */

/** Расширение кода или листа стилей — одним образцом на весь инструмент.
 *
 * Заведён после того, как восемь мест спрашивали его порознь и каждое называло
 * один язык стилей из пяти. Проект на обычных модулях CSS от этого терял адреса
 * в прозе, разбор коротких имён и опознание токенов — по одной сверке за место,
 * и каждый раз молча. Один образец нельзя поправить наполовину.
 */
export const CODE_OR_STYLE = /\.(tsx?|css|scss|sass|less|styl)$/;

/** Языки стилей — ОДНОЙ строкой, из которой собираются все образцы.
 *
 * Предикаты уже сводили это к одному месту, но образцы, перечисляющие
 * расширения внутри себя, остались порознь: их восемь, и каждый называл
 * один язык стилей. Самый дорогой — тот, которым инструмент ЧИТАЕТ адреса
 * из базы: файл `.css`, названный в карте, не разбирался как адрес вовсе,
 * то есть запись была, и не видел её никто. Проект на обычных модулях CSS
 * не мог закрыть покрытие карты в принципе.
 */
export const STYLE_ALT = "css|scss|sass|less|styl";

/** Код или стиль — альтернатива для образцов, а не готовый образец. */
export const CODE_STYLE_ALT = "[jt]sx?|" + STYLE_ALT;

/** Разбор вывода сверки: секция → МНОЖЕСТВО её строк находок.
 *
 * Аргументов два намеренно. Перенос строк — соглашение вызывающего, а не
 * этого разбора; заодно два аргумента выводят функцию из-под переборa
 * самопроверки, который умеет только да/нет, а здесь ответ — отображение.
 * Держит её набор тестов, а не таблица случаев.
 *
 * Прежде на этом месте стоял ФЛАГ «красная или нет», и его не хватало
 * сразу дважды. Сверка, красная ДО поломки, оставалась красной и после —
 * флаг не менялся, и рецепт числился промолчавшим. То есть в живом
 * проекте, где красные сверки есть по определению, фальсифицировать их
 * было нельзя вовсе: здоровая сверка выглядела сломанной.
 */
export const sectionsOf = (out, newline) => {
  const found = new Map();
  const lines = out.split(newline);
  for (let i = 0; i < lines.length; i += 1) {
    const head = /^=== (.+) ===$/.exec(lines[i]);
    if (head === null) continue;
    const red = new Set();
    for (let j = i + 1; j < lines.length && !/^=== /.test(lines[j]); j += 1)
      if (/^ {4}\S/.test(lines[j])) red.add(lines[j]);
    found.set(head[1], red);
  }
  return found;
};

/** Что сделал посаженный слом — по ВСЕМУ прогону, а не в одной секции.
 *
 * Четыре исхода:
 *
 *   секции нет в выводе после поломки          → рецепт устарел;
 *   секция появилась, которой не было          → поймала;
 *   в целевой секции прибавились строки        → поймала;
 *   целевая не изменилась, прибавилось в другой→ поломка ушла не туда:
 *     рецепт мимо, и сверка, ради которой он написан, ни при чём;
 *   не изменилось нигде                        → не дошла ни до одной.
 *
 * Последнее читается «здесь ломать нечего ЛИБО сверка слепа» — две вещи, и
 * разделить их нечем. Но прежде в этой куче лежали ещё две: отравленная
 * соседом песочница и сверка, красная до поломки. Обе закрыты, и остаток
 * назван честно, а не выдан за одну болезнь.
 *
 * Часть сверок печатает секцию ТОЛЬКО когда есть что сказать: звенья
 * цепочки без инструмента, версия среды, скрипты без описания. У здоровой
 * такой сверки секции в выводе нет вовсе, и «нет секции» для неё —
 * ЗДОРОВЬЕ, а не устаревший рецепт: появление секции после поломки и есть
 * её срабатывание. Прежде прогон объявлял неисправимым то, что исправно.
 */
export const classifyRun = (clean, after, section) => {
  const grew = (was, now) => [...now].some((l) => !was.has(l));
  const wasThere = clean.has(section);
  if (!after.has(section))
    return {
      how: "broken",
      why: wasThere
        ? " — секция пропала из вывода"
        : " — секции в выводе нет ни до, ни после",
    };
  if (!wasThere) return { how: "caught" };
  if (grew(clean.get(section), after.get(section))) return { how: "caught" };
  for (const [name, red] of after) {
    if (name === section) continue;
    if (!clean.has(name) || grew(clean.get(name), red))
      return {
        how: "astray",
        why: " — легла, но её приняла сверка «" + name + "»",
      };
  }
  return { how: "nowhere" };
};

/** Первый адрес рецепта фальсификации, выводящий из песочницы, — иначе
 * пустая строка.
 *
 * Песочница лежит внутри корня репозитория, и адрес, поднимающийся выше её
 * корня, после склейки с ней указывает в рабочее дерево: рецепт кладёт
 * поломку туда, где работают, и прогон, оборванный посередине, её там
 * оставляет. Такой адрес приходит из поля настройки — папка решений или
 * настроек, объявленная выше корня, — и из рецепта проекта, написанного
 * руками. Переименование одиночного рецепта считается от корня песочницы,
 * шага составного — от папки его файла: так их исполняет режим. */
export const sandboxEscape = (recipe) => {
  const climbs = (p) => {
    let depth = 0;
    for (const part of String(p).replace(/\\/g, "/").split("/")) {
      if (part === "..") depth -= 1;
      else if (part !== "" && part !== ".") depth += 1;
      if (depth < 0) return true;
    }
    return false;
  };
  for (const step of recipe.edits ?? [recipe]) {
    const own = [
      step.file,
      step.create?.path,
      step.mkdir,
      step.copyTo,
      step.appendFrom?.seed,
    ].find((p) => p !== undefined && climbs(p));
    if (own !== undefined) return own;
    if (step.rename === undefined) continue;
    const from = recipe.edits === undefined ? "" : (step.file ?? "") + "/..";
    if (climbs(from + "/" + step.rename)) return step.rename;
  }
  return "";
};

/** Обход ворот git в команде оболочки — причина, иначе пустая строка.
 *
 * Ворота перед коммитом стоят хуком git, и снимает их сама команда:
 * `commit --no-verify` либо коротко `-n`, подмена `core.hooksPath` ключом
 * `-c`, запись в эту настройку или её снятие. Разбирается оболочка, а не
 * подстрока: флаг в тексте сообщения, в доводе `echo` и в теле встроенного
 * документа командой не является, и запрет на нём учил бы обходить страж.
 * Команда внутри `sh -c`, `bash -c` и `eval` разбирается тем же порядком.
 * Запись в настройку пути хуков обвязки законна: её делает посадка.
 *
 * Подстановку флага и псевдоним разбор не ловит: страж стоит против обхода по
 * привычке, а прошедший мимо обход краснит ревизия сводов по истории. */
export const gitHookBypass = (command) => {
  const OWN_HOOKS = ".claude/hooks/git";
  const own = (value) =>
    value.replace(/^\.\//, "").replace(/\/+$/, "") === OWN_HOOKS;
  // Тела встроенных документов — данные, а не команды.
  const kept = [];
  let until = null;
  for (const line of String(command).split(NEWLINE)) {
    if (until !== null) {
      if (line.trim() === until) until = null;
      continue;
    }
    kept.push(line);
    const doc = /<<-?\s*(['"]?)([A-Za-z_][A-Za-z0-9_]*)\1/.exec(line);
    if (doc !== null) until = doc[2];
  }
  const body = kept.join(NEWLINE);
  const commands = [];
  let words = [];
  let word = "";
  let open = false;
  let quote = null;
  const endWord = () => {
    if (open) words.push(word);
    word = "";
    open = false;
  };
  const endCommand = () => {
    endWord();
    if (words.length) commands.push(words);
    words = [];
  };
  for (let i = 0; i < body.length; i += 1) {
    const ch = body[i];
    if (quote === "'") {
      if (ch === "'") quote = null;
      else word += ch;
    } else if (quote === '"') {
      if (ch === "\\" && i + 1 < body.length) {
        word += body[i + 1];
        i += 1;
      } else if (ch === '"') quote = null;
      else word += ch;
    } else if (ch === "\\" && i + 1 < body.length) {
      word += body[i + 1];
      open = true;
      i += 1;
    } else if (ch === "'" || ch === '"') {
      quote = ch;
      open = true;
    } else if (ch === " " || ch === "\t") endWord();
    else if (";&|()".includes(ch) || ch === NEWLINE) endCommand();
    else {
      word += ch;
      open = true;
    }
  }
  endCommand();
  const commitBypass = (args) => {
    const TAKES = "mFCct";
    const LONG_TAKES = new Set([
      "--message",
      "--file",
      "--author",
      "--date",
      "--reuse-message",
      "--reedit-message",
      "--fixup",
      "--squash",
      "--template",
      "--cleanup",
      "--trailer",
      "--pathspec-from-file",
    ]);
    for (let a = 0; a < args.length; a += 1) {
      const w = args[a];
      if (w === "--") break;
      if (w === "--no-verify") return "commit --no-verify";
      if (w.startsWith("--")) {
        if (LONG_TAKES.has(w)) a += 1;
        continue;
      }
      if (!w.startsWith("-") || w === "-") continue;
      for (let c = 1; c < w.length; c += 1) {
        if (w[c] === "n") return "commit -n";
        if (TAKES.includes(w[c])) {
          if (c === w.length - 1) a += 1;
          break;
        }
        if (w[c] === "S" || w[c] === "u") break;
      }
    }
    return "";
  };
  const configBypass = (args) => {
    const VALUED = new Set([
      "-f",
      "--file",
      "--blob",
      "--type",
      "--default",
      "--comment",
      "--value",
    ]);
    const READS = new Set([
      "--get",
      "--get-all",
      "--get-regexp",
      "--get-urlmatch",
      "--list",
      "-l",
    ]);
    const UNSETS = new Set(["--unset", "--unset-all"]);
    const positional = [];
    let read = false;
    let unset = false;
    for (let a = 0; a < args.length; a += 1) {
      const w = args[a];
      if (VALUED.has(w)) a += 1;
      else if (READS.has(w)) read = true;
      else if (UNSETS.has(w)) unset = true;
      else if (!w.startsWith("-")) positional.push(w);
    }
    let [key, ...rest] = positional;
    if (key === "get" || key === "list") return "";
    if (key === "unset") unset = true;
    if (key === "set" || key === "unset") [key, ...rest] = rest;
    if (key === undefined || key.toLowerCase() !== "core.hookspath") return "";
    if (read) return "";
    if (unset) return "config core.hooksPath";
    return rest.length > 0 && !own(rest[rest.length - 1])
      ? "config core.hooksPath"
      : "";
  };
  const VALUED_GLOBAL = new Set([
    "-C",
    "--git-dir",
    "--work-tree",
    "--namespace",
    "--super-prefix",
    "--attr-source",
  ]);
  const OVERRIDE = /^core\.hookspath=(.*)$/i;
  const check = (ws) => {
    let k = 0;
    while (k < ws.length && /^[A-Za-z_][A-Za-z0-9_]*=/.test(ws[k])) k += 1;
    const head = ws[k];
    if (head === undefined) return "";
    // Команда внутри оболочки и `eval` — та же команда.
    if (head === "eval") return gitHookBypass(ws.slice(k + 1).join(" "));
    if (/^(?:.*\/)?(?:ba|z|da)?sh$/.test(head)) {
      const at = ws.indexOf("-c", k + 1);
      return at < 0 || ws[at + 1] === undefined
        ? ""
        : gitHookBypass(ws[at + 1]);
    }
    if (!/^(?:.*\/)?git$/.test(head)) return "";
    let j = k + 1;
    while (j < ws.length && ws[j].startsWith("-")) {
      const opt = ws[j];
      if (opt === "-c") {
        const hit = OVERRIDE.exec(ws[j + 1] ?? "");
        if (hit !== null && !own(hit[1])) return "-c core.hooksPath";
        j += 2;
        continue;
      }
      j += VALUED_GLOBAL.has(opt) ? 2 : 1;
    }
    if (ws[j] === "commit") return commitBypass(ws.slice(j + 1));
    if (ws[j] === "config") return configBypass(ws.slice(j + 1));
    return "";
  };
  for (const ws of commands) {
    const why = check(ws);
    if (why !== "") return why;
  }
  return "";
};

/** Красен ли прогон — по НАПЕЧАТАННОМУ, а не по перечню имён.
 *
 * Находка — строка с отступом в четыре пробела, той же формой, какой её
 * узнаёт разбор фальсификации. Не роняют прогон секции двух родов:
 *
 *   предупреждение — его заголовок сам говорит `warning`;
 *   смягчённая — названа в `soft`. Флаг посадки смягчает сверки, чей
 *     предмет доделывает фаза 2: секция печатает найденное целиком — отчёт
 *     посадки берёт отсюда список её работы, — а код возврата от неё не
 *     зависит.
 *
 * Смягчение живёт ЗДЕСЬ, а не в отступе строки. Прежде вердикт собирался
 * перечнем имён, и две сверки стояли в нём с оговоркой «пока флаг поднят —
 * ноль». Перечень заменили судом по напечатанному, и оговорки пропали вместе
 * с ним: фаза 1 пустого проекта стала кончаться красной сверкой базы на
 * незаполненных правилах, которые заполняет фаза 2, — при тексте посадки,
 * обещающем обратное. Третья сверка смягчалась отступом в два пробела, и
 * её рецепт при поднятом флаге будил не её, а соседку. Найдено посадкой
 * руками в пустой проект. */
export const printedIsRed = (lines, warning, soft) => {
  let quiet = false;
  for (const line of lines) {
    const title = /^=== (.+) ===$/.exec(line);
    if (title !== null) {
      quiet = title[1].includes(warning) || soft.has(title[1]);
      continue;
    }
    if (!quiet && /^ {4}\S/.test(line)) return true;
  }
  return false;
};
